import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"周易口义","description":"周易口义 - 周易口义","frontmatter":{"title":"周易口义","description":"周易口义 - 周易口义"},"headers":[],"relativePath":"zh/classics/kouyi/001.md","filePath":"zh/classics/kouyi/001.md"}'),r={name:"zh/classics/kouyi/001.md"};function o(i,a,c,p,d,u){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易口义",tabindex:"-1"},[n("周易口义 "),e("a",{class:"header-anchor",href:"#周易口义","aria-label":"Permalink to “周易口义”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：周易口义十二卷，宋倪天隐述其师胡瑗之说也。瑗字翼之，泰州如皋人。用范仲淹荐，由布衣拜校书郎，历太学博士，致仕归。事迹具宋史本传。天隐始末未详。叶祖洽作陈襄行状，称襄有二妹，一适进士倪天隐，殆即其人。董□严陵集载其桐庐县令题名碑记一篇，意其尝官睦州也。其说易以义理为宗。邵伯温闻见前录记程子与谢湜书，言读易当先观王弼、胡瑗、王安石三家。三原刘绍攽周易详说曰：朱子谓程子之学源于周子，然考之易传，无一语及太极。于观卦彖辞云：「予闻之胡翼之先生居上为天下之表仪。」于大畜上九云：「予闻之胡先生曰：天之衢亨，误加何字。」于夬九三云：安定胡公移其文曰：「牡于𬱓，有凶，独行遇雨，若濡有愠。君子夬夬，无咎。」于渐上九云：安定胡公，以陆为逵。考伊川年谱称皇祐中游太学，海陵胡翼之先生方主教导，得先生所试，大惊，即延见，处以学职，意其时必从而受业焉。世知其从事濂溪，不知其讲易多本于翼之也。其说为前人所未及。今核以程傅良。然朱子语类亦称「胡安定易分晓正当」，则是书在宋时固以义理说易之宗也。宋志载瑗易解十卷，周易口义十卷。朱彝尊经义考引李振裕之说云：「瑗讲授之余，欲著述而未逮，其门人倪天隐述之，以非其师手著，故名曰口义。后世或称口义，或称易解，实无二书。」其说虽古无明文，今考晁公武读书志亦云胡安定易传，盖门人倪天隐所纂，非其自著，故序首称「先生曰」，其说与口义合，而列于易传条下，亦不另出口义一条。然则易解、口义确为一书，宋志误分为二明矣。乾隆四十三年三月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀周易口义发题",-1),e("p",null,"先生曰：夫易者，伏羲、文王、周公、孔子所以垂万世之大法，三才变易之书也。自伏羲仰观天文，俯察地理，始画八卦。故爻有九、六，以尽阴阳之数；位有三画，以尽三才之道；写天、地、雷、风、水、火、山、泽之象，以尽天下之用；明、健、顺、动、入、止、说、陷、明之体，以尽天下之理。然而伏羲之时，世质民淳，巧伪未兴，诈端未作，故虽三画，亦可以尽吉凶之变。自神农至尧、舜，莫不取法八卦之象，以为大治之本。历夏沿商，以及桀、纣之世，民欲丛生，奸伪万状，礼隳乐缺，天下纷然。故三爻不能尽万物之消长，究人心之情伪。文王有大圣之才，罹于忧患，观纣之世，小人在位，诈伪日炽，思周身之防，达忧患之情，通天人之渊蕴，明人事之始终，遂重卦为六十四，重爻为三百八十四，又于逐卦之下为之彖辞。故天地通变之道，万物情伪之理，一备于此。然谓之易者，按乾凿度云：「易一名而含三义：简易也，不易也，变易也。」故颖达作疏，洎崔觐、刘正简皆取其说。然谓不易、简易者，于圣人之经，缪妄殆甚。且仲尼曰：「名不正则言不顺，言不顺则事不成。」是言凡兴作之事，先须正名，名正则事方可成。况圣人作易，为万世之大法，岂复有二三之义乎？按掦子曰：「阴不极则阳不生，乱不极则德不形。」又系辞曰：",-1),e("p",null,"「易穷则变，变则通，通则久。」又云：「生生之谓易。」是大易之作，专取变易之义。盖变易之道，天人之理也。以天道言之，则阴阳变易而成万物，寒暑变易而成四时，日月变易而成昼夜。以人事言之，则得失变易而成吉凶，情伪变易而成利害，君子小人变易而成治乱。故天之变易，则归乎生成，而自为常道；若人事变易，则固在上位者裁制之如何耳。何则？在位之人，苟知其君子小人相易而为治乱，则当常进用君子，而摈斥小人，则天下常治而无乱矣。知其情伪相易而成利害，当纯用情实而黜去诈伪，则所为常利而无害矣。知其得失相易而成吉凶，当就事之得，而去事之失，则其行事常吉而无凶矣。是皆人事变易，不可不慎也。故大易之作，专取变易之义。谓之周易者，自伏羲画卦，文王重之，又从而为之彖辞，至周公又为之爻辞，仲尼又十翼之。数圣相继，其道大备于周，故曰「周易」。谓之「上经」、「下经」者，自乾、坤至坎、离三十卦谓之上经，自咸、恒至未济三十四卦谓之下经。然则所以分上下二经者，以简帙重大，故分之也。乾、坤者，天地之象；坎、离者，日月之象，故取以为上经。咸、恒者，夫妇之义；既济、未济，人伦终始之道，故取以为下经。先儒亦常谓不分之即无损于义，分之亦无害其实，但以简帙重大而分之也。乾传者，乾，卦名也；传，传也。言传述圣人之法，以示万世也。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
